r=pathlib.Path(__file__).parent;deadline=time.monotonic()+1800
while time.monotonic()<deadline:
 p=r/'verification-commands.json';x=json.loads(p.read_text()) if p.exists() else []
 if any(v['exit_code'] for v in x):raise SystemExit('verification failed; native services not started')
 if len(x)==4:break
