import json,pathlib,re,subprocess,collections
r=pathlib.Path(__file__).parent;rows=json.loads((r/'before-cp.json').read_text());service='surprising-aeron-core/surprising-aeron-service/target/classes/'
names=[x['owner'] for x in rows if x['path'].startswith(service)]
with (r/'service-javap.txt').open('w') as out:subprocess.run(['javap','-p','-c','-s','-classpath',service,*[n.replace('/','.') for n in names]],stdout=out,check=True)
uses=collections.defaultdict(list);owner=None;method=None;desc=None;header=None
for line in (r/'service-javap.txt').read_text().splitlines():
 m=re.search(r'\b(?:class|interface) ([\w.$]+)',line)
 if m and line.rstrip().endswith('{') and not line.startswith(' '):owner=m[1].replace('.','/');method=desc=None
 if line.startswith('  ') and not line.startswith('    ') and line.strip().endswith(';'):
  header=line.strip();method=header.split('(',1)[0].split()[-1].split('.')[-1] if '(' in header else None
 if line.startswith('    descriptor:') and method:desc=line.split(':',1)[1].strip()
 m=re.search(r'\d+:\s+(getfield|putfield)\s+.*// Field ([^:]+):(.+)$',line)
 if m:
  key=m[2].replace('"','');field_owner,_,field_name=key.rpartition('.')
  uses[(field_owner or owner,field_name,m[3])].append({'opcode':m[1],'caller':owner,'method':method,'descriptor':desc})
mainrefs=collections.defaultdict(set)
for x in rows:
 if '/target/test-classes/' in x['path']:continue
 for t,o,n,d in x['refs']:
  if t in (10,11):mainrefs[(o,n,d)].add(x['owner'])
candidates=[]
for x in rows:
 if not x['path'].startswith(service):continue
 for n,d,f in x['fields']:
  if f&8:continue
  found=uses.get((x['owner'],n,d),[]);reads=[u for u in found if u['opcode']=='getfield']
  if not reads or all(not mainrefs[(u['caller'],u['method'],u['descriptor'])] for u in reads):
   candidates.append({'owner':x['owner'],'field':n,'descriptor':d,'reads':reads,'writes':[u for u in found if u['opcode']=='putfield']})
(r/'field-candidates.json').write_text(json.dumps(candidates,indent=2)+'\n')
print('classes',len(names),'candidate fields',len(candidates))
for x in candidates:print(x['owner'],x['field'],'READ',[(y['method'],y['descriptor']) for y in x['reads']])
